 const result=transactStoryEvent(activeGameStorage(),s,action,{afterCommitCandidate:next=>{syncReturnRingRecipe(next);return true;}});if(idleExecution)idleExecutionResult=result;
 if(result.ok){s=result.game;lastCommittedGameRaw=JSON.stringify(s);e=normalizeEncounterElements(s.activeEncounter??null);if(action.type==='scenario'||action.type==='encounter'){view='battle';lastStep=Date.now();logs.unshift('继续当前剧情目标');}else if(action.type==='enter'||action.type==='retreat'){race=AREAS[s.siteId]?.race??s.race;selectedPlannedArea=AREAS[s.siteId]?.number??1;view='region';}else if(action.type==='use-tool'){race=AREAS[s.siteId]?.race??s.race;selectedPlannedArea=AREAS[s.siteId]?.number??1;view='region';toast('封印核心已解除，旧制楔钉已消耗；进度已保存。');}else if(action.type==='personal-step')toast(result.value?.hint??result.value?.message??'行动进度已保存');else if(action.type==='personal-pause')toast('个人线已暂存，可继续主线；稍后从原进度继续。');else if(action.type==='finish')toast('已记录这段经历');}
 else toast(result.reason==='storage'?'保存失败，这段对话尚未提交，可以重试。':'场景、地点或进度已经变化；尚未推进剧情。');
