 if(b.dataset.returnRingCraft){if(sandboxSession||forgeBusy)return true;if(!flushEventSnapshot())return true;const result=craftReturnRing(activeGameStorage(),s);if(result.ok){s=result.game;lastCommittedGameRaw=JSON.stringify(s);selected=result.value.id;lastForgeResult=result.value.id;toast('归途之环已制成');}else toast(result.reason==='balance-unconfirmed'?'稀有掉落参数尚待确认，尚未消耗材料。':result.reason==='storage'?'保存失败，未扣料；可以重试。':'当前不能制造归途之环');render();return true;}
 if(!b.dataset.npcAction)return false;
 const id=b.dataset.npcEvent,action=b.dataset.npcAction;if(sandboxSession||forgeBusy)return true;
