function restSeconds(){return Math.max(0,Math.ceil(((s.restUntil||0)-Math.max(Date.now(),s.lastHealthClock||0))/1000));}
function restLabel(){let n=restSeconds();return Math.floor(n/60)+':'+String(n%60).padStart(2,'0');}
